INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''garment specification sheet'' (spec sheet) typically used for in production?', '["Providing detailed measurements, construction details, and tolerances for a specific garment style, used as the reference for both production and quality checking","A document listing only the factory''s machine inventory","A record of worker attendance for a specific production line","A marketing document describing a garment''s retail price"]'::jsonb, 'Providing detailed measurements, construction details, and tolerances for a specific garment style, used as the reference for both production and quality checking', 'A spec sheet documents exact measurements (POMs), construction methods, and tolerances for a garment style, serving as the authoritative reference both for how the garment should be made and for checking whether finished garments meet requirements.', 1, '{"spec-sheet"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''CAD marker nesting'' intended to optimize?', '["Arranging pattern pieces as tightly and efficiently as possible within the marker to minimize fabric waste","The color sequence used when printing a garment design","The order in which garments are sewn on a production line","The physical location of machines in a factory layout"]'::jsonb, 'Arranging pattern pieces as tightly and efficiently as possible within the marker to minimize fabric waste', 'Marker nesting is the process (often computer-assisted) of arranging pattern pieces as closely and efficiently as possible within the fabric width to maximize marker efficiency and minimize wasted fabric.', 1, '{"marker-nesting"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''buttonholer'' machine used for in garment sewing?', '["Creating reinforced buttonhole openings in fabric, often with a bound or stitched edge to prevent fraying","Attaching buttons only, without creating any opening","Cutting fabric into pattern pieces","Pressing finished garments before packaging"]'::jsonb, 'Creating reinforced buttonhole openings in fabric, often with a bound or stitched edge to prevent fraying', 'A buttonholer machine cuts and simultaneously stitches around a buttonhole opening, creating a clean, reinforced edge that resists fraying from repeated button insertion/removal.', 1, '{"buttonholer"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''bartack'' stitch used for in garment construction?', '["A small, dense reinforcement stitch applied at points of high stress (like pocket corners or belt loops) to prevent seam failure","The main construction stitch used for long straight seams","A decorative stitch used only on formal wear","A stitch used exclusively for attaching woven care labels"]'::jsonb, 'A small, dense reinforcement stitch applied at points of high stress (like pocket corners or belt loops) to prevent seam failure', 'A bartack is a short, dense zigzag-type reinforcement stitch applied at stress points (pocket openings, belt loop ends) where a garment experiences repeated pulling force, preventing the seam from ripping open at that specific point.', 1, '{"bartack"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why would a factory intentionally apply a bartack at a jeans pocket corner rather than relying on the regular seam stitching alone?', '["Pocket corners experience concentrated repeated stress (from hands going in/out), and regular seam stitching alone is more likely to fail there without extra reinforcement","Bartacks are purely decorative and provide no additional structural strength","Regular seam stitching is always stronger than any bartack reinforcement","Bartacks are applied randomly with no relationship to stress points on a garment"]'::jsonb, 'Pocket corners experience concentrated repeated stress (from hands going in/out), and regular seam stitching alone is more likely to fail there without extra reinforcement', 'Pocket corners endure repeated, concentrated pulling stress every time a hand goes in or out; a bartack''s dense reinforcement stitching specifically resists this stress far better than the standard seam stitch alone, preventing premature seam failure at that high-stress point.', 2, '{"bartack-reinforcement"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''thread breakage rate'' a quality/efficiency metric for on a sewing line?', '["How frequently sewing thread breaks during stitching, which causes production stoppages and potential seam defects if not caught","The rate at which garments are shipped from the factory","The percentage of fabric wasted during cutting","The speed at which fabric is dyed in the wet process department"]'::jsonb, 'How frequently sewing thread breaks during stitching, which causes production stoppages and potential seam defects if not caught', 'Thread breakage rate tracks how often sewing thread snaps during stitching — each break stops that operator''s work and, if unnoticed, can leave an incomplete/weak seam, making this an important efficiency and quality metric to monitor.', 1, '{"thread-breakage"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What might cause an elevated thread breakage rate on a sewing line, beyond simple thread quality issues?', '["Incorrect machine tension settings, a damaged needle, or an inappropriate needle/thread combination for the fabric being sewn","Thread breakage is always caused exclusively by poor-quality thread, with no other possible contributing factor","Machine tension settings have no relationship to thread breakage under any circumstance","Needle condition never affects thread breakage rate"]'::jsonb, 'Incorrect machine tension settings, a damaged needle, or an inappropriate needle/thread combination for the fabric being sewn', 'Beyond thread quality itself, elevated thread breakage often traces to mismatched machine tension, a damaged/incorrect needle (burrs, wrong size for the fabric), or an unsuitable needle-thread-fabric combination — all worth investigating when breakage rates spike.', 2, '{"thread-breakage-causes"}'::text[]);
